// Навигация: deep link (если в приложении есть схема — APP_SCHEME) или через нижнее меню.
import { driver } from '@wdio/globals';
import { byText, tapText, byTextMatches, pageCounter } from './ui.ts';

export const TABS = ['תהילים', 'תפילות', 'בית', 'המסע שלי', 'ברכות'] as const;
export type Tab = (typeof TABS)[number];

/** Открыть маршрут приложения, как в web-тестах: '/prayer/mincha_ashkenaz', '/tehilim/39'. */
export async function openRoute(route: string) {
  const scheme = process.env.APP_SCHEME;           // например «ohrhageula» — уточнить в app.json при сборке
  if (!scheme) throw new Error('APP_SCHEME не задан: deep link недоступен, используйте навигацию через меню');
  const url = `${scheme}://${route.replace(/^\//, '')}`;
  if (driver.isAndroid) {
    await driver.execute('mobile: deepLink', { url, package: process.env.APP_ANDROID_PACKAGE });
  } else {
    await driver.execute('mobile: deepLink', { url, bundleId: process.env.APP_IOS_BUNDLE });
  }
}
export const hasDeepLinks = () => Boolean(process.env.APP_SCHEME);

export async function goTab(tab: Tab) {
  await tapText(tab);
}

/** Открыть молитву: deep link, иначе «תפילות» → карточка → второй тап открывает молитву (S-27). */
export async function openPrayer(key: string, catalogTitle: string) {
  if (hasDeepLinks()) return openRoute(`/prayer/${key}`);
  await goTab('תפילות');
  const card = await byText(catalogTitle);
  await card.waitForDisplayed();
  await card.click();                               // 1-й тап — раскрыть (время/колокольчик)
  const open = await byText(`פתיחת ${catalogTitle}`);
  if (await open.isDisplayed().catch(() => false)) await open.click();
  else await card.click();                          // 2-й тап — открыть
  await (await byTextMatches('\\d+ מתוך \\d+')).waitForDisplayed();
}

/** Перейти на страницу N (קודם/המשך). */
export async function goToPage(n: number, total: number) {
  for (let i = 0; i < total + 2; i++) {
    const before = await pageCounter();
    const cur = Number(before.split(' ')[0]);
    if (cur === n) return;
    await tapText(cur > n ? 'קודם' : 'המשך');
    // дождаться смены счётчика, иначе следующий шаг прочитает старое значение
    await driver.waitUntil(async () => (await pageCounter()) !== before, { timeout: 10000, timeoutMsg: 'Счётчик страниц не изменился' });
  }
  throw new Error(`Не удалось перейти на страницу ${n}`);
}
